) AS (
  VALUES 
    (64::BIGINT, 'Nota mental, no matricular con él. El curso se basa en trabajos en grupo, por lo que si te toca un mal grupo, perdiste (son grupos aleatorios). Trabajos muy largos y poco entendibles, es un curso de 3 créditos y parecen 6. Usa aula virtual con videos muy aburridos y con temas importantes.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2026-10-15T00:00:00+00:00'::TIMESTAMPTZ, '20fda10be78138fe935f8a4fe348b08b1685ae6eeb18e7afe9108cbbe30b550b'::TEXT, ARRAY[2465]::BIGINT[]),
    (64::BIGINT, 'El curso se pasa, pero es un verdadero dolor de cabeza, te puede llegar a estorbar con otras materias que SÍ son importantes, por lo que no lo lleve en un semestre cargado. Todo el curso es un desorden y por eso es que el mae pone a los estudiantes a dar la clase.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'efa5ac08388d1d1e44ca0f3e29975dc8de56cee2ca1b7fd90e252f99a74febea'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'Si alguien piensa: "No puede ser tan malo como dicen los comentarios", si, si es tan malo como dicen los comentarios, dice que no quiere joder a los estudiantes pero en todo el semestre se encarga de hacer la vida imposible, con fechas de entrega rigidas + Volumen de tareas complicadas etc...'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'be18d32b4495ff7f9725827ddcaef80baef1147850e8de30833126d31c1b5326'::TEXT, ARRAY[2454]::BIGINT[]),
    (64::BIGINT, 'Simplemente pésimo. Es un vago, las últimas 5 semanas del curso no dió clases, fueron presentaciones de los estudiantes. Para ganar más de 2 millones de colones debería de por lo menos tener la plataforma ordenada, pero ni eso. Mediocre y altanero.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2026-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'e764bb665e1533eea7320d53f80f2bd115aa8450c90a1911586d7805f05be062'::TEXT, ARRAY[2454]::BIGINT[]),
    (64::BIGINT, '1 hora en esta clase con Ronald, se siente eterna. Nunca da la clase él y deja demasiados trabajos. Insisten demasiado en la idea de emprender y ser "el propio jefe" cuando la mayoría solo llevamos el curso porque existe dentro del plan de estudios. No lo lleve en su semestre más pesado.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-04-30T00:00:00+00:00'::TIMESTAMPTZ, '1489612d31cc3f48010f8c8c0bd5289296856c2b802e58c1bf81117e8184b667'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'Es un señor muy necio, en las clases muy pocas veces explicas la materia porque la aulta invertida donde uno tiene que explicar los temas a los demás. Nos salvamos del shark tank por el tema de la amenza, y es muy necio con el proyecto final porque tiene que ser innovador. Busquen mejores opciones'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, '357b7062d451396a2e72ec43d5f383a2c6a3752a0eb42efea7aeb323fb819e06'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'Desordenado. Irrespetuoso. Se trae a sus amigotes a las evaluaciones en la clase. Dice comentarios racistas hacia los asiáticos y antisemitas. No controla el temperamento y si pudiera le pegaría a los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-10-23T00:00:00+00:00'::TIMESTAMPTZ, '9003fb7e9d23f41742a6b99c692cef70eec81368be040b32c29b098cee60f993'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'Muy desordenado, todo es pura aula invertida, explica basicamente lo mismo en clase que explica desde semana 1 hasta 16. Cuesta mucho que alguien vaya al día con la materia pero porque ponerse a ver videos fuera de clase todas las semanas no inspira a aprender. Pero es buena persona.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'cb54af748d4c1721439707fcd06045518e193e9e2faab1a216d1f6b77ef1e20d'::TEXT, ARRAY[2454]::BIGINT[]),
    (64::BIGINT, 'Preparese para planear un emprendimiento INNOVADOR, además de ayudar a una PYME con lo visto en clase. El crea los grupos. El emprendimiento se trabaja durante el curso para la presentación final tipo shark tank. Pero el curso es pasable. Si lee esto profe, que buen sandwitch de pollo ????'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Muchos proyectos grupales']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, '904ce03a3e22499234fbf9aa4a47a978dd36e5b4efdd31805a142c96fdd42df7'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'Desde semana 1 queda claro el desorden, un cronograma completamente desactualizado que él cambia y no se digna a siquiera dejarlo apuntado... TODO es en grupos y nunca va a entender lo que quiere; entrega notas tarde, usted termina dando las clases y los trabajos tras de ambiguos: pesados y largos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2025-05-21T00:00:00+00:00'::TIMESTAMPTZ, 'b7c44453020a73c4db8ed7727ff5bdd43cf20e07659f8537e06df16625eca091'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'El mae se enfoca mucho en producción y en la aplicación de inteligente artificial. Es super complicado, los desafíos son muy demandante. ?? Evitenlo si pueden.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2025-03-05T00:00:00+00:00'::TIMESTAMPTZ, '0f57b34e5a5b86d044822360ffac558c25870a63d9b29c5b05aef4e75c3db1e6'::TEXT, ARRAY[2465]::BIGINT[]),
    (64::BIGINT, 'El profesor no da el curso enfocado en administración, sino que en ingeniería y pretende que uno sepa todos los conceptos. No explica bien lo que quiere y pretende que uno sepa usar de todo con IA'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'ba898ec00ed1bd001daa3e4da7a4ab744311b75716d9a0d64d684a0133e68d00'::TEXT, ARRAY[2465]::BIGINT[]),
    (64::BIGINT, 'Muy desordenado con las claes, normalmente el curso que imparta sera una carga extra para usted y para colmo es un pedante. EVITAR A TODA COSTA'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-12-25T00:00:00+00:00'::TIMESTAMPTZ, 'c0d55e78289469d042438d2d72df21b15a6fd18ed2a4ee7aba35df0fb4484f01'::TEXT, ARRAY[2465]::BIGINT[]),
    (64::BIGINT, 'De los peores profesores que he tenido. Es MUY buena gente y buena nota, pero como profesor es sumamente malo. Es incapaz explicar la materia, así que recurre a videos de otros profesores para que uno entienda. Hace los examenes con IA (llenos de errores y materia que nunca dió). Demasiado estrés.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, '98ff7772c0f7c311ac46e755e055dbabb2e1b54f4fc54a5f0072fe268890a5af'::TEXT, ARRAY[2465]::BIGINT[]),
    (64::BIGINT, 'NO META CON ÉL y si tiene que: No se confié. Al principio parece un profe incluso medio buena nota, pero conforme avanza el semestre va a entender la calificación que tiene aquí. Califica duro, quiere perfección y da una clases horribles, lleva unos invitados que son peor que él. Evítelo si puede.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-11-15T00:00:00+00:00'::TIMESTAMPTZ, '38189b4575ef99014898a66d43908df52a323dff7d18707448c2bbacf63dda03'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'Asco de persona. No tiene consideración alguna por el tiempo de los estudiantes. Cambia su criterio de evaluación cada vez que se le pregunta, no es consistente, hace el curso sumamente impredecible. No lleve con este señor, va a odiar cada minuto de clase.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-11-05T00:00:00+00:00'::TIMESTAMPTZ, 'ebcd8c39057a726970bbe386caeebbfc2fcb96dee2193bbbedea7ab9cfb8b6d6'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'Si tiene la oportunidad de llevar el curso con él, desaprovechela'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-10-28T00:00:00+00:00'::TIMESTAMPTZ, 'e5012541547e279affae6b39ee72df9cd9d894fceae13f0752f7ef510e205b60'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'No explica, no da materia y material es de otros años con links que no funcionan y con fechas que no calzan. Pone DEMASIADOS trabajos y todo en grupo de ir a buscar empresas para los 5 retos que son casi que un proyecto final cada uno MÁS EL RETO'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-05-10T00:00:00+00:00'::TIMESTAMPTZ, '95f1de822d2b2649c8333f6f6663568f81c836d616abce51746220cd3ae0c41e'::TEXT, ARRAY[2454]::BIGINT[]),
    (64::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-29T00:00:00+00:00'::TIMESTAMPTZ, '648a60e05e5a5914a1eb87ff316edd29ac870f80e911ae19519e68ac3c94e307'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'Sabe mucho pero no sabe explicar bien. Participe en clases con eso ayuda mucho y estudie bastante porque el profesor pregunta cualquier estudiante y con eso se da cuenta si estudió o no'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f0d76441824d7bb3dbab1dc1bf2c1d2f4360c6c42a2932b28e20601b3d9f2b42'::TEXT, ARRAY[2454]::BIGINT[]),
    (64::BIGINT, 'Es un curso de mucha tarea y mucho trabajo, no obstante, al menos en el caso de mi grupo, el profesor fue muy abierto a las retroalimentaciones como estudiante y nos ayudo mucho. El profesor ayuda bastante si el ve que uno le pone ganas a la materia.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '3ea7c684a6ed480e4f7ffa21ddbfb2850c169aadc14732b05b1610e8e488c0d0'::TEXT, ARRAY[2454]::BIGINT[]),
    (64::BIGINT, 'EVITENLO. Todo es en grupos. Trabajos enormes todas las semanas. Las clases son con "aula invertida" entonces consume demasiado tiempo y el profe es demasiado cerrado en su opinion, nunca el estudiante va a tener la razon.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'b7293be0d971535573e523a64e9651702e2071372ec14806ea6e47a7b8ac28ac'::TEXT, ARRAY[2454]::BIGINT[]),
    (64::BIGINT, 'No matricule con él, es la peor desición de su vida, espere trabajar mucho, para que cuando le revisen diga que es una porquería, que no era lo que él quería, aunque usted le dio exactamente lo que pidió, poca palabra'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'da62d2019013d150fb60aa62ff3ca4408cbbca0d5e50806afaa027e2e9cc2bf7'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'Pésimo profesor, deja trabajos grupales en los que ni siquiera brinda una explicación clara, no le importa su opinión ni lo que usted piense, NO pierdan el tiempo con él'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-01-23T00:00:00+00:00'::TIMESTAMPTZ, '7d9a01599de6ccf61f82568c0fc87a5743704a3a19060b98082301c5f7e8195d'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'No se entiende lo que quiere, califica duro y con criterios que nada que ver, los trabajos son excesivos y super innecesarios y pide demasiado'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-11-23T00:00:00+00:00'::TIMESTAMPTZ, '28f66c4853d168bdac8c25840dba2afc43f3b0a8e232301255b5e01a174f7a8c'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'Cursar con este profesor es una pérdida de tiempo horrible, si tienes interés alguno en la materia o quieres evitarte un dolor de cabeza cuando el profesor se inventa un detalle para el desarrollo de un proyecto o contradice directamente las especificaciones de las tareas le recomiendo evitarlo.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-11-08T00:00:00+00:00'::TIMESTAMPTZ, '860fa3bd46af97ece821553c7bfffd3540db7dec00d054cbd131b64d02f40dac'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'Este profesor solo hará que tu salud mental se deteriore. Este profesor no da explicaciones claras para las tareas, le dedicamos más tiempo a temas que no califica y sus clases son muy pesadas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2022-09-21T00:00:00+00:00'::TIMESTAMPTZ, '026120bc72888ae1b802621839a903233feb53a70cdebabfb4ab1251590e397e'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'No hay claridad. No esta abierto a comentarios, su opinión no le importa. No existe comunicación fuera de clase. Trabajos confusos. Explicación ambigua y sin ningún objetivo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2022-09-21T00:00:00+00:00'::TIMESTAMPTZ, '035d8022d18b4622f6fc5b793e2bdbb971660defa19feff788a569dbb2017964'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'Pésimo, lo peor que tiene la escuela de administración. El curso no tiene exámenes sino 5 “retos”; que en otras palabras son trabajos de manualidades y todos deben ser grupales y de forma presencial. De lo contrario es imposible desarrollarlos. No sabe dar instrucciones claras, es confrontativo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '7d2e146ab68770eb8c0626f58a56084eb9f44e026933117f8d753d514a3ffc54'::TEXT, ARRAY[2454]::BIGINT[]),
    (64::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-15T00:00:00+00:00'::TIMESTAMPTZ, '6e9c3d2b7fbfe13b7d1e0e3ff8c154c39843cd09c1a5607c43bf33fb2c733aca'::TEXT, ARRAY[4152]::BIGINT[]),
    (64::BIGINT, 'El profesor no sabe dar las clases. Es muy desordenado. Asigna trabajos que no van con el curso. Califica duro porque no se le puede quedar bien en nada. Sin embargo, el curso es fácil si usted estudia, los temas son sencillos y solo requieren de práctica. Consigase un buen grupo y listo.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, '723a91eda0dc3a2ba417f9a02471b88c055cd053bb8b58fe953afcca20105f8a'::TEXT, ARRAY[2465]::BIGINT[]),
    (64::BIGINT, 'Lo único que dio ganas de emprender fue el proceso de retiro de curso, NO MATRICULEN CON EL, tal vez sin matricula la escuela entienda que está mal y lo quite.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-10-14T00:00:00+00:00'::TIMESTAMPTZ, '267cfc58303724cbf1997d43c6ef714d515e5c4df1ef1051cbf2a3f0ac35fcb7'::TEXT, ARRAY[965]::BIGINT[]),
    (64::BIGINT, 'Nunca se sabe lo que quiere, no da instrucciones claras y nunca pierde.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, '223840b24aaa18afc2f6052f2d1e13524475effbea7f903e5a0bedaad174e62d'::TEXT, ARRAY[2454]::BIGINT[]),
    (64::BIGINT, 'El profesor no sabe dar una clase, nombres, perdi 6 meses de mi vida con el nombres cho'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('5','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-23T00:00:00+00:00'::TIMESTAMPTZ, '99600315282cab8447d9a14f95055ffcd8c6a04b2921650424eaf093d5007a03'::TEXT, ARRAY[2955]::BIGINT[]),
    (64::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-01-04T00:00:00+00:00'::TIMESTAMPTZ, '10eb18aee816169f7a89097b763f5be2b38229757fd90921edac4ff8c4e53fad'::TEXT, ARRAY[2955]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
